Lemma AERRNO_val : AERRNO = 0x65d40c.
Proof. reflexivity. Qed.

(* [comment removed for export] *)
Lemma aconst_ok_errno : aconst_ok (AERRNO, AERRNO + 4).
Proof.
  apply aconst_ok_intro; unfold ASHBASE_CELL, AMEMCPYP_CELL, AINITED_CELL, AHIEND_CELL, ADYING_CELL, APGSZ_CELL, ACANPOISON_CELL, AF_DCO_CELL, AVERBOSITY_CELL,
    AREAL_TLSGA_CELL, ATSD_CELL, AREGISTERED_CELL, ACOVFLAG_CELL, sh, AIMG_LO, AIMG_TOP, ASHADOW_BASE, AERRNO, ATP in *; lia.
Qed.

Section HCW.
  Context {HCEIL : HeapCeil}.

  Lemma stack0_ok_errno : stack0_ok (AERRNO, AERRNO + 4).
  Proof. right. cbn [fst snd]. pose proof aceil_facts as (AF & _). unfold AERRNO, ATP, sh, ASHADOW_BASE. Z.div_mod_to_equations. lia. Qed.

  Lemma win_fr_errno : forall ff k, win_fr ff k (AERRNO, AERRNO + 4).
  Proof. intros ff k. left. cbn [fst snd]. unfold AERRNO, ATP, ALOWSH_LO. lia. Qed.

  Lemma awin_errno : awin (AERRNO, AERRNO + 4).
  Proof. split; [apply aconst_ok_errno| split; [apply stack0_ok_errno| left; cbn [fst snd]; unfold AERRNO, ATP, ALOWSH_LO; lia]]. Qed.

  (* [comment removed for export] *)
  Lemma errno_accessible : forall m, ACONST m -> accessible m 0x65d408 8.
  Proof. intros m AC. exact (ACONST_img_accessible m 0x65d408 8 AC ltac:(vm_compute; reflexivity)). Qed.

